#include "pch.h"
#include "EditorFrame.h"
namespace sct::ui {
bool EditorFrame::SweepDown(CPoint point){if(!sweepMode_||style_.tool!=core::Tool::Select||GetKeyState(VK_CONTROL)<0||GetKeyState(VK_SHIFT)<0||GetKeyState(VK_MENU)<0)return false;if(!ScreenRect({0,0,document_.Width(),document_.Height()}).PtInRect(point))return true;sweepPoints_={ImagePoint(point)};sweepRevision_=revision_;sweepExpected_=Selection();sweepGesture_=true;++sweepEpoch_;SetCapture();InvalidateRect(canvas_,FALSE);return true;}
bool EditorFrame::SweepMove(CPoint point){if(!sweepGesture_)return false;const auto p=ImagePoint(point);if(sweepPoints_.size()<4096&&(sweepPoints_.back().x!=p.x||sweepPoints_.back().y!=p.y))sweepPoints_.push_back(p);InvalidateRect(canvas_,FALSE);return true;}
bool EditorFrame::SweepUp(CPoint point){if(!sweepGesture_)return false;SweepMove(point);sweepGesture_=false;if(GetCapture()==this)ReleaseCapture();const auto revision=sweepRevision_,epoch=sweepEpoch_;auto path=std::move(sweepPoints_);const auto expected=sweepExpected_;sweepExpected_.clear();const auto state=document_.State();activeAction_=WorkRefinement;StartWork([state,path=std::move(path),revision,epoch,expected]{WorkResult r;r.action=WorkRefinement;r.command=SweepObjects;r.revision=revision;r.preview=epoch;r.expected=expected;r.selected=core::SweepSelection(state,path);return r;});InvalidateRect(canvas_,FALSE);return true;}
void EditorFrame::CancelSweep(bool mode){const bool captured=sweepGesture_;sweepGesture_=false;if(mode)sweepMode_=false;++sweepEpoch_;sweepPoints_.clear();sweepExpected_.clear();if(captured&&GetCapture()==this)ReleaseCapture();if(::IsWindow(m_hWnd))InvalidateRect(canvas_,FALSE);}
bool EditorFrame::PaintSweep(CDC& dc){if(!sweepGesture_)return false;if(sweepPoints_.size()>1){std::vector<POINT> points;for(auto p:sweepPoints_)points.push_back(ScreenRect({p.x,p.y,p.x,p.y}).TopLeft());CPen pen(PS_DOT,1,RGB(170,180,190));auto* old=dc.SelectObject(&pen);dc.Polyline(points.data(),int(points.size()));dc.SelectObject(old);}return true;}
}
